create trigger monthly_preview_special_binding_immutable before update or delete
  on public.monthly_preview_daily_special_bindings for each row
  execute function public.proplet_daily_special_binding_immutable();

create function public.proplet_monthly_preview_special_binding_v1(p_puzzle_id text)
returns public.daily_special_bindings language plpgsql stable security invoker set search_path='' as $$
declare binding public.daily_special_bindings;
begin
  if public.proplet_monthly_preview_trusted_v1() then
    select * into binding from public.monthly_preview_daily_special_bindings where puzzle_id=p_puzzle_id;
  else
    select * into binding from public.daily_special_bindings where puzzle_id=p_puzzle_id;
  end if;
  return binding;
end $$;
revoke all on function public.proplet_monthly_preview_special_binding_v1(text) from public,anon,authenticated;
grant execute on function public.proplet_monthly_preview_special_binding_v1(text) to service_role;

do $patch$
declare source text; boundary text;
begin
  boundary:='select * into v_binding from public.daily_special_bindings where puzzle_id=v_puzzle_id;';
  source:=pg_get_functiondef('public.proplet_submit_daily_special_v1(uuid,text,text,text,jsonb)'::regprocedure);
  if position(boundary in source)=0 then raise exception 'MONTHLY_EXTRA_WRITER_BINDING_BOUNDARY_CHANGED'; end if;
  execute replace(source,boundary,'select * into v_binding from public.proplet_monthly_preview_special_binding_v1(v_puzzle_id);');
  boundary:='select * into b from public.daily_special_bindings where puzzle_id=new.puzzle_id;';
  source:=pg_get_functiondef('public.proplet_daily_special_identity_guard()'::regprocedure);
  if position(boundary in source)=0 then raise exception 'MONTHLY_EXTRA_GUARD_BINDING_BOUNDARY_CHANGED'; end if;
  execute replace(source,boundary,'select * into b from public.proplet_monthly_preview_special_binding_v1(new.puzzle_id);');
end $patch$;
commit;
